import React from "react";
import {
  FormItem,
  Input,
  ArrayTabs,
  FormButtonGroup,
  Submit,
} from "@storage-fe/formily-arco";
import { createForm } from "@formily/core";
import { FormProvider, createSchemaField } from "@formily/react";

const SchemaField = createSchemaField({
  components: {
    FormItem,
    Input,
    ArrayTabs,
  },
});

const form = createForm();

const schema = {
  type: "object",
  properties: {
    string_array: {
      type: "array",
      title: "字符串数组",
      "x-decorator": "FormItem",
      maxItems: 3,
      "x-component": "ArrayTabs",
      items: {
        type: "string",
        "x-decorator": "FormItem",
        title: "字符串",
        required: true,
        "x-component": "Input",
      },
    },
    array: {
      type: "array",
      title: "对象数组",
      "x-decorator": "FormItem",
      maxItems: 3,
      "x-component": "ArrayTabs",
      items: {
        type: "object",
        properties: {
          aaa: {
            type: "string",
            "x-decorator": "FormItem",
            title: "AAA",
            required: true,
            "x-component": "Input",
          },
          bbb: {
            type: "string",
            "x-decorator": "FormItem",
            title: "BBB",
            required: true,
            "x-component": "Input",
          },
        },
      },
    },
  },
};

export default () => {
  return (
    <FormProvider form={form}>
      <SchemaField schema={schema} />
      <FormButtonGroup>
        <Submit onSubmit={console.log}>提交</Submit>
      </FormButtonGroup>
    </FormProvider>
  );
};
